        // one that establishes exhaustion, so there is no read ahead.
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // A read failure, a mapper failure or a consumer-injected throw reaches
      // this point; remember it so the finally block keeps it as the
      // propagated error even when closing also fails.
